alter policy profiles_insert_self on public.profiles to authenticated with check (id = (select auth.uid()));
alter policy profiles_select_self on public.profiles to authenticated using (id = (select auth.uid()));
alter policy profiles_update_self on public.profiles to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
alter policy organizations_bootstrap_insert on public.organizations to authenticated with check ((select auth.uid()) is not null);
alter policy memberships_bootstrap_insert on public.organization_memberships to authenticated with check ((user_id = (select auth.uid())) and role='administrator' and not exists (select 1 from public.organization_memberships existing where existing.organization_id=organization_memberships.organization_id));
alter policy site_memberships_insert_self on public.site_memberships to authenticated with check ((user_id = (select auth.uid())) and exists (select 1 from public.sites s where s.id=site_memberships.site_id and private.has_org_role(s.organization_id,array['administrator'::text])));
alter policy site_memberships_select_self_or_admin on public.site_memberships to authenticated using ((user_id = (select auth.uid())) or exists (select 1 from public.sites s where s.id=site_memberships.site_id and private.has_org_role(s.organization_id,array['administrator'::text])));
alter policy safety_records_insert_operational on public.safety_records to authenticated with check ((created_by = (select auth.uid())) and private.has_org_role(organization_id,array['administrator'::text,'supervisor'::text,'safety_coordinator'::text,'worker'::text]));
alter policy safety_records_select_staff_client_or_self on public.safety_records to authenticated using (private.has_org_role(organization_id,array['administrator'::text,'supervisor'::text,'safety_coordinator'::text,'client_viewer'::text]) or (created_by = (select auth.uid())) or ((worker_id is not null) and private.is_self_worker(worker_id)));
alter policy workers_select_authorized on public.workers to authenticated using (private.has_org_role(organization_id,array['administrator'::text,'supervisor'::text,'safety_coordinator'::text,'client_viewer'::text]) or (user_id = (select auth.uid())));
